<?php

declare(strict_types=1);

namespace ItalyStrap\Empress;

use Brick\VarExporter\ExportException;
use Brick\VarExporter\VarExporter;
use ItalyStrap\Config\ConfigInterface;
use Safe\DateTimeImmutable;
use Webimpress\SafeWriter\Exception\ExceptionInterface as FileWriterException;
use Webimpress\SafeWriter\FileWriter;

final class ProvidersCache implements ProvidersCacheInterface
{
    private const CACHE_TEMPLATE = <<<'EOT'
<?php

declare(strict_types=1);

/**
 * This file generated by %s at %s
 */

%s
EOT;
    private string $file;
    private int $fileMode;
    private bool $enabled;

    public function __construct(string $file = '', int $fileMode = 0666, bool $enabled = false)
    {
        $this->file = $file;
        $this->fileMode = $fileMode;
        $this->enabled = $enabled;
    }

    /**
     * @param ConfigInterface<array-key, mixed> $config
     */
    public function read(ConfigInterface $config): bool
    {
        if (!$this->enabled) {
            return false;
        }

        if (
            $this->file === ''
            || !file_exists($this->file)
            || !is_file($this->file)
            || !is_readable($this->file)
        ) {
            return false;
        }

        $config->merge($this->loadCacheFile($this->file));
        return true;
    }

    /**
     * @param ConfigInterface<array-key, mixed> $config
     */
    public function write(ConfigInterface $config): void
    {
        if (!$this->enabled || $this->file === '') {
            return;
        }

        try {
            $contents = sprintf(
                self::CACHE_TEMPLATE,
                self::class,
                // Write an alternative to date('c')
                (new DateTimeImmutable('now'))->format('c'),
                VarExporter::export(
                    $config->toArray(),
                    VarExporter::ADD_RETURN | VarExporter::CLOSURE_SNAPSHOT_USES
                )
            );
        } catch (ExportException $e) {
            throw new \ErrorException('Configuration cannot be cached', 0, 1, __FILE__, __LINE__, $e);
        }

        $this->writeCache($this->file, $contents, $this->fileMode);
    }

    private function writeCache(string $cachedConfigFile, string $contents, int $mode): void
    {
        try {
            FileWriter::writeFile($cachedConfigFile, $contents, $mode);
        } catch (FileWriterException $e) {
            throw new \ErrorException('Configuration cache cannot be written', 0, 1, __FILE__, __LINE__, $e);
        }
    }

    /**
     * @return array<array-key, mixed>
     */
    private function loadCacheFile(string $cachedConfigFile): array
    {
        try {
            $config = require $cachedConfigFile;
        } catch (\Throwable $e) {
            throw new \ErrorException('Configuration cache cannot be read', 0, 1, __FILE__, __LINE__, $e);
        }

        if (!\is_array($config)) {
            throw new \ErrorException('Configuration cache must return an array');
        }

        return $config;
    }
}
